async function writeChurnCsv(name) {
  const tempDir = await mkdtemp(path.join(tmpdir(), "insight-specialist-ui-"));
  const csvPath = path.join(tempDir, `${name}.csv`);
  await writeFile(
    csvPath,
    [
      "customer_id,signup_date,canceled,revenue",
      "c1,2024-01-01,true,19.99",
      "c2,2024-02-01,false,49.50",
    ].join("\n"),
  );
  return csvPath;
}

async function submitQuestionRun(question, csvPath) {
  await driver.url(harness.baseUrl);

  const textarea = await deepElement(driver, ["insight-specialist-app", "question-run-form", "textarea[name='question']"]);
  await textarea.setValue(question);

  const fileInput = await deepElement(driver, ["insight-specialist-app", "question-run-form", "input[type='file']"]);
  await fileInput.setValue(csvPath);

  const submit = await deepElement(driver, ["insight-specialist-app", "question-run-form", "button[type='submit']"]);
  await submit.click();
}

async function processMapStates() {
  return await driver.execute(() => {
    const app = document.querySelector("insight-specialist-app");
    const processMap = app?.shadowRoot?.querySelector("process-map");
